#include <stdio.h>

int main() {
    int a = 6;
    int b = 7;

    if (a > b) {
        printf("XX\n");
    } else {
        printf("XY\n");
    }

    return 0;
}

        mov     a_r, 6                          // int a = 6;
        mov     b_r, 7                          // int b = 7;

        cmp     a_r, b_r                        // if (a > b)
        b.gt    greater_than                    // true: jump to the if part

        // else part: b.gt did not jump, so execution carries on here
        ldr     x0, =fmt_xy
        bl      printf
        // without this branch, execution falls into the if part below
        b       end

greater_than:
        ldr     x0, =fmt_xx
        bl      printf

end:

